// Layout maths of CPython 3.12 `argparse.HelpFormatter`, ported 1:1.
//
// Pure functions only: no I/O, no state.  The two entry points mirror
// `ArgumentParser.format_usage()` and `ArgumentParser.format_help()`, i.e. the
// formatter is driven, the sections are rendered, and finally
// `HelpFormatter.format_help()` normalises the blank lines.

// `HelpFormatter(width=None)` uses `shutil.get_terminal_size().columns - 2`.
// Callers are expected to pass an explicit width; 80 - 2 is the CPython fallback.
const DEFAULT_WIDTH = 78;

// `_Section.format_help()` indents its body by one level (`indent_increment=2`),
// so every action line and every `add_argument()` measurement carries this.
const SECTION_INDENT = 2;
const INDENT = ' '.repeat(SECTION_INDENT);

// HelpFormatter._whitespace_matcher = re.compile(r'\s+', re.ASCII)
const WHITESPACE = /[ \t\n\r\f\v]+/g;

// HelpFormatter._long_break_matcher = re.compile(r'\n\n\n+')
const LONG_BREAK = /\n\n\n+/g;

// The `part_regexp` of `_format_usage`: a parenthesised or bracketed group stays
// whole, everything else is split on whitespace.  Note that this splits an
// unbracketed (i.e. required) option from its metavar: `--a A` becomes the two
// parts `--a` and `A`, which is what makes the wrapped usage line break between
// them.
const PART_RE = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

/** HelpFormatter._metavar_formatter, for a single-value slot. */
function metavarFor(action, defaultMetavar) {
  // `choices` is never set by this program's parser, so only the metavar /
  // default branches of CPython's helper are needed.
  return action.metavar != null ? action.metavar : defaultMetavar;
}

/**
 * HelpFormatter._format_args for `nargs=None` — the only shape produced here
 * (a `store` action consuming exactly one value).
 */
function formatArgs(action, defaultMetavar) {
  return metavarFor(action, defaultMetavar);
}

/** One entry of HelpFormatter._format_actions_usage. */
function usagePart(action) {
  if (action.optionStrings.length === 0) {
    // positional: `_get_default_metavar_for_positional` is `action.dest`
    return formatArgs(action, action.dest);
  }
  const optionString = action.optionStrings[0];
  let part;
  if (action.nargs === 0) {
    // Action.format_usage() -> the first option string on its own (`-h`)
    part = optionString;
  } else {
    // `_get_default_metavar_for_optional` is `action.dest.upper()`
    part = optionString + ' ' + formatArgs(action, action.dest.toUpperCase());
  }
  // "make it look optional if it's not required" (no mutually exclusive groups)
  if (!action.required) {
    part = '[' + part + ']';
  }
  return part;
}

/** HelpFormatter._format_actions_usage: the parts joined by single spaces. */
function formatActionsUsage(actions) {
  return actions.map(usagePart).join(' ');
}

/**
 * The `get_lines()` closure inside `_format_usage`: greedy filling of `parts`
 * into `width` columns.  When `prefix` is given the first line is measured
 * against the prefix instead of the indent, and has the indent stripped again
 * so the caller can prepend `'usage: '`.
 */
function getLines(parts, indent, prefix, width) {
  const lines = [];
  let line = [];
  let lineLen = (prefix === null ? indent.length : prefix.length) - 1;
  for (const part of parts) {
    if (lineLen + 1 + part.length > width && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length > 0) {
    lines.push(indent + line.join(' '));
  }
  if (prefix !== null) {
    // `prefix` is only passed together with `prog` as the first part, so there
    // is always at least one line here.
    lines[0] = lines[0].slice(indent.length);
  }
  return lines;
}

/**
 * HelpFormatter._format_usage (with `usage=None`), minus the trailing '\n\n'
 * that `format_help()` would strip away again.
 *
 * @param {{prog: string, actions: object[], width?: number}} options
 * @returns {string} e.g. 'usage: PROG [-h] --a A --b B'
 */
export function formatUsage({ prog, actions, width = DEFAULT_WIDTH }) {
  const prefix = 'usage: ';

  // split optionals from positionals
  const optionals = [];
  const positionals = [];
  for (const action of actions) {
    (action.optionStrings.length > 0 ? optionals : positionals).push(action);
  }

  const optUsage = formatActionsUsage(optionals);
  const posUsage = formatActionsUsage(positionals);
  const actionUsage = [optUsage, posUsage].filter((s) => s).join(' ');
  let usage = [prog, actionUsage].filter((s) => s).join(' ');

  // wrap the usage parts if it's too long (`text_width` == width, the current
  // indent is 0 while the usage is being formatted)
  if (prefix.length + usage.length > width) {
    const optParts = [...optUsage.matchAll(PART_RE)].map((m) => m[0]);
    const posParts = [...posUsage.matchAll(PART_RE)].map((m) => m[0]);
    let lines;

    if (prefix.length + prog.length <= 0.75 * width) {
      // prog goes on the first line, the parts hang under its right edge
      const indent = ' '.repeat(prefix.length + prog.length + 1);
      if (optParts.length > 0) {
        lines = getLines([prog, ...optParts], indent, prefix, width);
        lines.push(...getLines(posParts, indent, null, width));
      } else if (posParts.length > 0) {
        lines = getLines([prog, ...posParts], indent, prefix, width);
      } else {
        lines = [prog];
      }
    } else {
      // prog is too wide: it gets a line of its own
      const indent = ' '.repeat(prefix.length);
      lines = getLines([...optParts, ...posParts], indent, null, width);
      if (lines.length > 1) {
        // re-flow so optionals and positionals never share a line
        lines = [
          ...getLines(optParts, indent, null, width),
          ...getLines(posParts, indent, null, width),
        ];
      }
      lines = [prog, ...lines];
    }
    usage = lines.join('\n');
  }

  return prefix + usage;
}

/** HelpFormatter._format_action_invocation. */
function invocation(action) {
  if (action.optionStrings.length === 0) {
    return metavarFor(action, action.dest);
  }
  if (action.nargs === 0) {
    // takes no value: '-h, --help'
    return action.optionStrings.join(', ');
  }
  // takes a value: '-s ARGS, --long ARGS'
  const argsString = formatArgs(action, action.dest.toUpperCase());
  return action.optionStrings.map((o) => o + ' ' + argsString).join(', ');
}

/**
 * textwrap.wrap() as used by `_split_lines`: greedy, whitespace-only breaks.
 * The help strings of this program contain no word longer than `width` and no
 * hyphens, so `break_long_words` / `break_on_hyphens` never fire.
 */
function wrap(text, width) {
  if (text === '') {
    return [];
  }
  const lines = [];
  let current = '';
  for (const word of text.split(' ')) {
    if (current === '') {
      current = word;
    } else if (current.length + 1 + word.length <= width) {
      current += ' ' + word;
    } else {
      lines.push(current);
      current = word;
    }
  }
  lines.push(current);
  return lines;
}

/** HelpFormatter._split_lines: collapse whitespace runs, then wrap. */
function splitLines(text, width) {
  return wrap(text.replace(WHITESPACE, ' ').trim(), width);
}

/** HelpFormatter._format_action, at a current indent of one section level. */
function formatAction(action, { helpPosition, helpWidth, actionWidth }) {
  const header = invocation(action);
  const helpLines = action.help ? splitLines(action.help, helpWidth) : [];

  // no help: the invocation is the whole entry
  if (helpLines.length === 0) {
    return INDENT + header + '\n';
  }

  const parts = [];
  let indentFirst;
  if (header.length <= actionWidth) {
    // short invocation: the help starts on the same line, padded to the column
    parts.push(INDENT + header.padEnd(actionWidth) + '  ');
    indentFirst = 0;
  } else {
    // long invocation: the help starts on the next line
    parts.push(INDENT + header + '\n');
    indentFirst = helpPosition;
  }
  parts.push(' '.repeat(indentFirst) + helpLines[0] + '\n');
  for (const line of helpLines.slice(1)) {
    parts.push(' '.repeat(helpPosition) + line + '\n');
  }
  return parts.join('');
}

/**
 * ArgumentParser.format_help(): usage block, then one section per action group,
 * then `HelpFormatter.format_help()`'s blank-line normalisation.
 *
 * @param {{prog: string, actions: object[],
 *          groups: {title: string, actions: object[]}[],
 *          width?: number}} options
 * @returns {string} help text ending in exactly one '\n'
 */
export function formatHelp({ prog, actions, groups, width = DEFAULT_WIDTH }) {
  // HelpFormatter.__init__
  const maxHelpPosition = Math.min(24, Math.max(width - 20, 4));

  // HelpFormatter.add_argument(): invocation length plus the section indent,
  // accumulated over every action handed to the formatter.
  let actionMaxLength = 0;
  for (const group of groups) {
    for (const action of group.actions) {
      actionMaxLength = Math.max(actionMaxLength, invocation(action).length + SECTION_INDENT);
    }
  }

  // HelpFormatter._format_action
  const dimensions = {
    helpPosition: Math.min(actionMaxLength + 2, maxHelpPosition),
    helpWidth: 0,
    actionWidth: 0,
  };
  dimensions.helpWidth = Math.max(width - dimensions.helpPosition, 11);
  dimensions.actionWidth = dimensions.helpPosition - SECTION_INDENT - 2;

  // add_usage() emits 'usage: ...\n\n'; description/epilog are absent here.
  const parts = [formatUsage({ prog, actions, width }) + '\n\n'];

  for (const group of groups) {
    const items = group.actions.map((action) => formatAction(action, dimensions)).join('');
    // `_Section.format_help` returns '' for an empty section, so a group
    // without actions contributes nothing at all (not even its heading).
    if (items === '') {
      continue;
    }
    parts.push('\n' + group.title + ':\n' + items + '\n');
  }

  // HelpFormatter.format_help(): collapse 3+ newlines, strip, add exactly one.
  const help = parts.join('').replace(LONG_BREAK, '\n\n');
  return help.replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
}

// scratch differential harness (not part of /output)
import { formatUsage, formatHelp } from '/output/lib/argparse/formatter.mjs';
import { execFileSync } from 'node:child_process';

const helpAction = {
  optionStrings: ['-h', '--help'],
  dest: 'help',
  nargs: 0,
  required: false,
  metavar: null,
  help: 'show this help message and exit',
};
const aAction = {
  optionStrings: ['--a'],
  dest: 'a',
  nargs: null,
  required: true,
  metavar: null,
  help: undefined,
};
const bAction = { ...aAction, optionStrings: ['--b'], dest: 'b' };

const actions = [helpAction, aAction, bAction];
const groups = [
  { title: 'positional arguments', actions: [] },
  { title: 'options', actions },
];
const prog = 'test3_executable';

function columnsFor(env) {
  // shutil.get_terminal_size(): COLUMNS if it parses to an int > 0, else the
  // terminal size (a pipe -> OSError) else the (80, 24) fallback.
  if (env === undefined) return 80;
  const n = /^[+-]?\d+$/.test(env.trim()) ? parseInt(env, 10) : 0;
  return n > 0 ? n : 80;
}

function ref(args, env) {
  const e = { ...process.env };
  delete e.COLUMNS;
  if (env !== undefined) e.COLUMNS = env;
  try {
    const out = execFileSync('/workspace/dataset/test3_executable', args, {
      env: e,
      encoding: 'buffer',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return { stdout: out.toString(), stderr: '' };
  } catch (err) {
    return { stdout: err.stdout.toString(), stderr: err.stderr.toString() };
  }
}

const widthsEnv = [undefined, '20', '21', '25', '30', '40', '60', '79', '80', '100', '200', '0', 'garbage'];
for (let c = 1; c <= 120; c++) widthsEnv.push(String(c));

let fails = 0;
for (const env of widthsEnv) {
  const width = columnsFor(env) - 2;
  const label = env === undefined ? 'unset' : JSON.stringify(env);

  const mineHelp = formatHelp({ prog, actions, groups, width });
  const refHelp = ref(['--help'], env).stdout;
  if (mineHelp !== refHelp) {
    fails++;
    console.log(`HELP MISMATCH COLUMNS=${label} (width=${width})`);
    console.log('--- mine ---\n' + JSON.stringify(mineHelp));
    console.log('--- ref  ---\n' + JSON.stringify(refHelp));
  }

  const mineErr =
    formatUsage({ prog, actions, width }) +
    '\n' +
    `${prog}: error: the following arguments are required: --a, --b\n`;
  const refErr = ref([], env).stderr;
  if (mineErr !== refErr) {
    fails++;
    console.log(`ERR MISMATCH COLUMNS=${label} (width=${width})`);
    console.log('--- mine ---\n' + JSON.stringify(mineErr));
    console.log('--- ref  ---\n' + JSON.stringify(refErr));
  }
}
console.log(fails === 0 ? `ALL OK (${widthsEnv.length} widths x 2 streams)` : `${fails} FAILURES`);
